var e="https://www.befiler.com/",a={seo:{title:"Befiler case study",description:"Befiler, Pakistan\u2019s online tax filing service: a customer dashboard, a staff portal, an agent portal and filing widgets embedded in six banking apps and a mobile wallet. Angular throughout, Urdu in right to left.",imageAlt:'Befiler case study cover: the Befiler mark above "Tax returns, filed from any app."'},hero:{tag:"Case study",pill:"2020 to now, junior to lead",line1:"Befiler.",line2:"Tax returns, filed from any app.",lede:"Pakistan\u2019s online tax filing service. Since 2020 I have built its customer dashboard, the staff portal behind it, an agent portal, and the filing widgets six banks and a mobile wallet embed in their own apps.",live:"Visit befiler.com",back:"View work"},meta:[{k:"Role",v:"Junior to lead frontend developer"},{k:"Timeline",v:"March 2020 to now"},{k:"Platforms",v:"Web, 6 bank apps, a wallet mini-app"},{k:"Stack",v:"Angular, TypeScript, Spring Boot, PHP"}],numbers:[{value:"11",label:"Angular apps: customer dashboard, staff portal, agent portal, bank widgets and wallet builds"},{value:"7",label:"host apps run the filing widget: six banks and the Easypaisa wallet"},{value:"6,800+",label:"commits across the repos since March 2020, about three in four of them mine"},{value:"375",label:"components in the staff portal, the largest of the apps"}],products:{title:"One platform, six products",sub:"Customers, bank customers, agents and staff each get their own app. All of them talk to one API, and a return started in any of them lands in the same queue.",items:[{icon:"phosphorSquaresFour",t:"Customer dashboard",who:"Taxpayers and small businesses",s:"Every service on one account: income tax returns, NTN, sales tax, trademarks and USA company services, with payments, documents, alerts and live chat.",tags:["63 lazy routes","English and Urdu","Firebase push","Family accounts"],wide:!0,featured:!0},{icon:"phosphorBank",t:"Bank widgets",who:"Customers inside six banking apps",s:"A slim filing app that opens inside HBL, Bank Alfalah, Allied Bank, MCB, UBL and Abhi, wearing each bank\u2019s colours.",tags:["One template","Six builds","Urdu, RTL"],wide:!1,featured:!1},{icon:"phosphorWallet",t:"Easypaisa mini-app",who:"Mobile wallet users",s:"Rebuilt in 2026 as a wallet mini-app: sign-in through the wallet\u2019s JavaScript bridge, payment in the wallet.",tags:["JS bridge","WebView"],wide:!1,featured:!1},{icon:"phosphorTray",t:"Staff portal",who:"Tax consultants, lawyers, sales, accounts, marketing, admins",s:"Work queues per service, assignment, leads, payments, refunds, reports, campaigns, WhatsApp and an AI assistant, all behind a permission matrix. Consultant and LLC manager portals live inside it.",tags:["375 components","Highcharts","FullCalendar","PDF export"],wide:!0,featured:!1},{icon:"phosphorStorefront",t:"Agent portal",who:"Company and external agents",s:"Agents register NTNs and file returns for their customers. Company agents run branches, sub-agents and promo codes.",tags:["Payment cart","Branches"],wide:!1,featured:!1},{icon:"phosphorGlobe",t:"befiler.com",who:"Everyone, before they sign up",s:"Plans, a salary tax calculator, NTN and ATL status checkers, sales tax and USA service pages, a blog and videos, in English and Urdu.",tags:["PHP","Vanilla JS","Gulp","SEO"],wide:!0,featured:!1}]},site:{title:"The front door: befiler.com",sub:"Plans, a salary tax calculator, NTN and ATL status checkers and a blog, in English and Urdu. PHP and vanilla JS with a Gulp build, so it paints fast for search.",heroAlt:'befiler.com home page: "Pakistan\u2019s easiest way to file your tax return" with Start Filing Now and WhatsApp buttons.',mobileAlt:"befiler.com on a phone: the same hero, stacked for a narrow screen.",plansAlt:"befiler.com plans: Essential, Priority and Premium Consultant filing, with prices and what each includes.",calcAlt:"befiler.com salary tax calculator: monthly salary, tax year, monthly tax and salary after tax.",plansCap:"Three filing plans",calcCap:"Salary tax calculator",note:"Screenshots of the live public site. Everything below the public site is shown as my own mockups."},services:{title:"More than income tax",sub:"Each service has its own page on befiler.com, its own flow in the dashboard and its own queue in the staff portal.",salesTax:{t:"Sales tax",s:"Registration with FBR or a provincial authority, monthly returns with sales and purchase reconciliation, nil returns, and help with notices, appeals and hearings. Each request becomes a case in the sales tax queue.",url:"befiler.com/sales-tax",alt:'befiler.com sales tax page: "Sales Tax Registration and Monthly Sales Tax Filing, Handled by Experts", with registration and filing cards below.',cardsAlt:"befiler.com sales tax services: registration, monthly filing, notices and audits, appeals and rectification, cases and court hearings.",cardsCap:"Sales tax, from registration to hearings",page:{t:"Sales tax, a landing page of its own",s:"befiler.com/sales-tax sells two services side by side, registration and monthly filing, each straight into its own flow, and backs them with support when a notice or audit arrives.",plansAlt:"befiler.com sales tax cards: Sales Tax Registration (FBR, provincial sales tax on services, STRN profile, complete support) and Monthly Sales Tax Filing (return preparation, sales and purchase reconciliation, payment and challan help, nil returns), beside 1000+ companies served, 20,000+ returns filed and 98% on-time filing.",plansCap:"Registration and monthly filing, each with its own start button",figures:[{v:"1,000+",k:"companies served"},{v:"20,000+",k:"returns filed"},{v:"98%",k:"filed on time"}],figuresNote:"Figures as befiler.com states them.",whoT:"Who it is for",who:["Retailers and wholesalers","Manufacturers and distributors","Service providers","Importers and exporters","Online sellers","IT and software companies","Consultants and agencies","Restaurants and hospitality"],backT:"After filing",back:["Sales tax notices and audits","Appeals and rectification","Representation before tax authorities","Case handling and documentation","Court hearings and appearances"]}},usa:{t:"USA filing and company formation",s:"An LLC or corporation in any state, a complete package with EIN and a US bank account, ITIN for non US citizens, federal and state tax filing, and US trademarks. Consultant and LLC manager portals run these cases.",url:"befiler.com/usa-services",alt:'befiler.com USA services page: "Form your LLC in the USA with our help and save up to $100", with Arrange a Call and WhatsApp buttons.',cardsAlt:"befiler.com USA price cards: US company registration, complete package, USA tax filing, ITIN and US trademark registration.",cardsCap:"USA packages"},also:"Also on the dashboard: business NTN, business and partnership returns, IRIS profile updates, trademark and copyright registration."},doors:{title:"One filing flow, many front doors",sub:"A return can start on befiler.com, in the dashboard, through an agent, or inside a bank or wallet app. Each door is its own Angular build talking to one API.",left:"Front doors",core:"Befiler API",coreSub:"Returns, payments, cases",right:"Back office",doorsList:[{icon:"phosphorGlobe",t:"befiler.com",s:"PHP, vanilla JS, Gulp"},{icon:"phosphorBrowser",t:"Customer dashboard",s:"Angular, English and Urdu"},{icon:"phosphorUsers",t:"Agent portal",s:"Agents file for customers"},{icon:"phosphorBank",t:"Bank widgets",s:"One build per bank"},{icon:"phosphorWallet",t:"Wallet mini-app",s:"Easypaisa JS bridge"}],backList:[{icon:"phosphorTray",t:"Staff portal",s:"Queues, assignment, reports"},{icon:"phosphorUserCircleCheck",t:"Consultant and LLC portals",s:"Cases, approvals, refunds"},{icon:"phosphorSealCheck",t:"FBR",s:"Filed by the tax team"}]},partner:{title:"Same widget, each bank\u2019s colours",sub:"One widget template, cloned per partner. A bank opens it inside its own app, the widget trades the handoff for a session, wears the bank\u2019s colours, and leaves payment to the bank.",pick:"Partner",waysTitle:"Three ways in",ways:[{tag:"HBL, Allied, MCB, UBL, Abhi",t:"Encrypted handoff",s:"The bank app opens the widget with an encrypted payload. The widget trades it for a session, then sends new customers to a short profile and returning ones to their dashboard."},{tag:"Bank Alfalah",t:"Issued token",s:"The bank issues a token before it opens the widget. The widget validates it and starts the session, with no second sign-in."},{tag:"Easypaisa",t:"Wallet bridge",s:"The mini-app asks the wallet\u2019s JavaScript bridge for an auth code, with the customer\u2019s consent to share name, phone and CNIC. Bridge callbacks run inside Angular, so the screen updates."}]},dashboard:{title:"The customer dashboard",sub:"Where returns are filed and every other service is bought and tracked. My first Befiler repo, from March 2020, and still the busiest: over 3,000 commits.",items:[{icon:"phosphorStack",t:"Three plans",s:"Essential to file yourself, Priority for an expert to do it, Premium for a personal certified consultant."},{icon:"phosphorCreditCard",t:"Payments",s:"Card, RAAST, bank transfer, Easypaisa and Foree, with a cart, OTP confirmation and payment history."},{icon:"phosphorUsersThree",t:"Family accounts",s:"File for family and friends from one sign-in, with linked accounts and authorised agents."},{icon:"phosphorChatCircleDots",t:"Alerts and chat",s:"Firebase push, notices, important dates and live chat with the tax team."},{icon:"phosphorCalculator",t:"Tools",s:"Salary tax calculator, NTN and ATL finders, and a feed of guides and videos."},{icon:"phosphorSignIn",t:"Sign-in and setup",s:"Email, Google or Facebook, then a one-time setup. Route guards keep setup and plan choice in order."}]},flow:{title:"From sign-up to submitted",sub:"The dashboard walks through every schedule FBR asks for. The bank widget keeps what a salaried customer needs, so a return takes a handful of screens.",tabs:{portal:"Customer dashboard",widget:"Bank widget"},portal:["Sign up","Plan","Tax year","Personal info","Income","Tax credits","Tax deducted","Wealth statement","Expenses","Wrap up","Payment","Review and track"],widget:["Handoff from the bank","Tax year","Income","Wealth statement","Pay in the bank app","Track"],incomeTitle:"Income, built from what you earn",income:["Salary","Business","Freelance","Services","Pension","Agriculture","Commission","Share of AOP","Rent","Capital gains","Profit on savings","Dividends"],wealthTitle:"Wealth statement",wealth:["Property","Vehicles","Bank accounts","Investments","Insurance","Possessions","Foreign assets","Cash","Loans"]},back:{title:"The staff portal",sub:"Every request lands in a queue. Consultants, lawyers, sales, accounts and marketing each see their part, and a permission matrix decides what each person can do.",rolesLabel:"Who signs in",roles:[{icon:"phosphorUserGear",t:"Admins"},{icon:"phosphorBriefcase",t:"Tax consultants"},{icon:"phosphorScales",t:"Lawyers"},{icon:"phosphorChartLine",t:"Sales agents and supervisors"},{icon:"phosphorReceipt",t:"Accounts"},{icon:"phosphorMegaphone",t:"Marketing"},{icon:"phosphorStorefront",t:"External agents"},{icon:"phosphorBuildings",t:"LLC managers"}],cards:[{icon:"phosphorTray",t:"Work queues",s:"A queue per service: NTN, returns on each plan, business returns, sales tax, trademark, copyright, USA and FBR challans."},{icon:"phosphorUserSwitch",t:"Assignment and SLAs",s:"Cases and leads go to the right person. A service builder sets each service\u2019s fields, documents, pricing, triggers and escalation."},{icon:"phosphorChartLine",t:"Leads and sales",s:"Leads, callbacks and a calendar with notes. Agent targets and commission on Highcharts dashboards."},{icon:"phosphorReceipt",t:"Payments and refunds",s:"Card, RAAST, bank transfer and cash, FBR challans, and refunds that pass consultant, supervisor, admin and finance."},{icon:"phosphorChartBar",t:"Reports",s:"About a dozen: payments, customers, performance, FBR challans, agents. PDF, Excel and CSV exports."},{icon:"phosphorBellRinging",t:"Campaigns",s:"Firebase push, scheduled alerts, promo codes and WhatsApp template broadcasts, with live progress streamed to the screen."},{icon:"phosphorWhatsappLogo",t:"WhatsApp and AI",s:"Several WhatsApp chats side by side for the team, and an AI assistant trained from files or question and answer pairs."},{icon:"phosphorShieldCheck",t:"Permissions",s:"Each permission is an action on a resource. A structural directive shows only what a user may do, and sessions and activity are logged."}],tracker:"Your return"},stack:{title:"The stack",sub:"Angular in every app, with the toolkit chosen per surface, and a Java and Spring Boot backend behind all of them.",groups:[{t:"Backend APIs",why:"Java and Spring Boot serve every app. I wrote APIs there too, including the YouTube sync: it pulls Befiler\u2019s videos from the YouTube Data API, and the customer dashboard shows the latest four as cards.",wide:!0,items:[{name:"Java",logo:"openjdk"},{name:"Spring Boot",logo:"springboot"},{name:"REST APIs",icon:"phosphorPlugs"},{name:"STOMP WebSockets",icon:"phosphorBroadcast"},{name:"Server-sent events",icon:"phosphorBroadcast"},{name:"YouTube Data API",logo:"youtube"}]},{t:"befiler.com",why:"Static first, for search and first paint.",items:[{name:"PHP",logo:"php"},{name:"Vanilla JS",logo:"javascript"},{name:"Gulp",logo:"gulp"},{name:"WordPress blog",logo:"wordpress"},{name:"On-page SEO",icon:"phosphorCode"}]},{t:"Customer dashboard",why:"Charts, push, videos and live updates for a long-lived account.",items:[{name:"Angular 13",logo:"angular"},{name:"RxJS",logo:"reactivex"},{name:"Bootstrap 5",logo:"bootstrap"},{name:"ng-bootstrap",logo:"bootstrap"},{name:"ngx-translate",icon:"phosphorTranslate"},{name:"ngx-charts",icon:"phosphorCode"},{name:"AngularFire push",logo:"firebase"},{name:"STOMP over SockJS",icon:"phosphorBroadcast"}]},{t:"Staff portal",why:"Desktop tools for people who work in it all day.",items:[{name:"Angular 13",logo:"angular"},{name:"Highcharts",icon:"phosphorCode"},{name:"FullCalendar",icon:"phosphorCode"},{name:"Rich text editor",icon:"phosphorCode"},{name:"jsPDF",icon:"phosphorFilePdf"},{name:"PDF.js",icon:"phosphorFilePdf"},{name:"Server-sent events",icon:"phosphorBroadcast"},{name:"Firebase web push",logo:"firebase"}]},{t:"Bank widgets and wallet",why:"Small bundles that load fast inside another app.",items:[{name:"Angular 13 and 14",logo:"angular"},{name:"ngx-translate",icon:"phosphorTranslate"},{name:"Urdu, RTL",icon:"phosphorTranslate"},{name:"Bootstrap grid only",logo:"bootstrap"},{name:"postMessage",icon:"phosphorPlugs"},{name:"Wallet JS bridge",icon:"phosphorPlugs"},{name:"Kotlin WebView harness",logo:"kotlin"}]},{t:"Agent portal",why:"A focused app for filing on someone else\u2019s behalf.",items:[{name:"Angular 13",logo:"angular"},{name:"Angular CDK",logo:"angular"},{name:"Bootstrap",logo:"bootstrap"},{name:"ng-bootstrap",logo:"bootstrap"}]},{t:"Across every app",why:"The same conventions, so anyone can move between repos.",wide:!0,items:[{name:"TypeScript",logo:"typescript"},{name:"SCSS",logo:"sass"},{name:"Lazy-loaded modules",logo:"angular"},{name:"Token refresh interceptors",icon:"phosphorLock"},{name:"Route guards",icon:"phosphorShieldCheck"},{name:"ng-select",icon:"phosphorCode"},{name:"ngx-mask",icon:"phosphorCode"}]}]},partners:{title:"Filed from inside your bank",sub:"The widget ships in six banking apps and a mobile wallet. befiler.com also lists its industry partners and collaborators.",embedded:"The widget runs inside",payments:"Payments and compliance",collab:"Partners and collaborators on befiler.com"},decisions:{title:"Decisions and what I\u2019d change",sub:"Years on one product teach you which shortcuts age well.",items:[{t:"A build per bank",s:"Each bank got its own clone of the widget template: colours, handoff and payment bridge. One bank\u2019s release never waited on another\u2019s. The cost is that a fix lands in every build, so the next step is one widget with partner config at runtime."},{t:"Payment stays with the host",s:"Inside a bank app the widget never sees card details. Some banks debit the account after an OTP in the widget; others take payment in their own app and hand the result back, and the widget checks until it settles."},{t:"A flow built from data",s:"The order of steps is computed from what the customer earns. Pick salary and rent, and only those schedules appear in the sidebar."},{t:"Permissions as data",s:"Staff roles change often. A permission is an action on a resource, stored per user, and the UI reads that list, so a new role needs no release."},{t:"Urdu, right to left",s:"The dashboard and newer widgets switch to Urdu with ngx-translate, flip the layout to RTL, and tell the API which language to answer in."},{t:"Static where it can be",s:"befiler.com stays PHP and vanilla JS with a Gulp build: fast first paint for search, calculators and status checkers, the blog pulled from WordPress."}]},next:{title:"Need a platform like this?",sub:"Multi-app Angular products, widgets that live inside other people\u2019s apps, and the back office behind them.",hire:"Hire me",other:"Next: Quorum"}},s=[{id:"hbl",name:"HBL",color:"#3f647d",ink:"#ffffff"},{id:"allied",name:"Allied Bank",color:"#0b2145",ink:"#ffffff"},{id:"alfalah",name:"Bank Alfalah",color:"#363636",ink:"#ffffff"},{id:"mcb",name:"MCB",color:"#2f7a29",ink:"#ffffff"},{id:"abhi",name:"Abhi",color:"#16775a",ink:"#ffffff"},{id:"easypaisa",name:"Easypaisa",color:"#4d6b00",ink:"#ffffff"}],t=[{name:"HBL",file:"hbl",w:96,h:96},{name:"UBL",file:"ubl",w:160,h:96},{name:"MCB",file:null,w:0,h:0},{name:"Allied Bank",file:"allied-bank",w:129,h:96},{name:"Bank Alfalah",file:"bank-alfalah",w:478,h:96},{name:"Abhi",file:null,w:0,h:0},{name:"Easypaisa",file:"easypaisa",w:232,h:65}],n=[{name:"RAAST",file:"raast",w:76,h:79},{name:"FBR",file:"fbr",w:174,h:77}],o=[{name:"Engro",file:"engro",w:142,h:96},{name:"ICMAP",file:"icmap",w:97,h:96},{name:"KCCI",file:"kcci",w:241,h:89},{name:"PSEB",file:"pseb",w:131,h:96},{name:"Telenor",file:"telenor",w:216,h:96},{name:"JS Bank",file:"js-bank",w:168,h:81},{name:"ACCA",file:"acca",w:96,h:96},{name:"Meezan Bank",file:"meezan",w:320,h:96},{name:"SECP",file:"secp",w:86,h:96},{name:"P@SHA",file:"pasha",w:152,h:42},{name:"NCC",file:"ncc",w:96,h:96},{name:"AWS",file:"aws",w:119,h:71}];export{e as a,a as b,s as c,t as d,n as e,o as f};
